/* Scope to this page wrapper (from your screenshot) */
#homePageMenu #section-actions,
#formLandingPageForm #section-actions {
  display: none !important;   /* hides the whole actions row that contains "Save" */
}

/* Extra safety: hide Save controls if they’re rendered without the section wrapper */
#homePageMenu .section-actions button,
#homePageMenu .section-actions input[type="submit"],
#formLandingPageForm .section-actions button,
#formLandingPageForm .section-actions input[type="submit"] {
  display: none !important;
}

/* Hide the "Print" link on this page only */
#homePageMenu a[href*="print"],
#homePageMenu .print,
#homePageMenu button.print {
  display: none !important;
}

#homePageMenu ~ a.print-button {
    display: none !important;
}

